<?php require_once __DIR__.'/../_bootstrap.php';$u=user();$q='%'.($_GET['q']??'').'%';$s=db()->prepare('SELECT s.*,p.name,p.brand,p.category,p.condition_status,p.unique_identifier,p.identifier_type,p.id product_id,r.id return_id,r.reason,r.returned_at,r.refund_amount FROM sales s JOIN products p ON p.id=s.product_id LEFT JOIN returns r ON r.sale_id=s.id WHERE s.seller_id=? AND (s.customer_name LIKE ? OR s.customer_phone LIKE ? OR p.name LIKE ? OR p.brand LIKE ?) ORDER BY s.sold_at DESC');$s->execute([$u['id'],$q,$q,$q,$q]);$rows=$s->fetchAll();$today=new DateTimeImmutable('today');foreach($rows as &$row){$row['warranty_valid']=!empty($row['warranty_ends_at'])&&$row['warranty_ends_at']>=$today->format('Y-m-d');$row['images']=product_images((int)$row['product_id']);}out(['success'=>true,'customers'=>$rows]);
